'use strict';
// AG160 REVIEW-ONLY signed queue transport contract. NO live network access.
// Hard-bound to reserved .invalid host + expressly injected offline fixture transport.
// This does not admit R212 code, deploy signed credentials, or provide a real signer.
// All signatures are generated by an externally injected signer; no key is stored here.
const BASE='https://tens-queue.review.invalid';
const PATHS={claim:'/internal/claim',complete:'/internal/complete',fail:'/internal/fail'};
const enc=new TextEncoder();
const hex=b=>[...new Uint8Array(b)].map(v=>v.toString(16).padStart(2,'0')).join('');
const b64url=b=>Buffer.from(b).toString('base64url');
function createOfflineSignedQueueClient({base=BASE,transport,signer,clock,nonceFactory,webcrypto}={}){
 if(base!==BASE)throw Error('REVIEW_ONLY_INVALID_BASE_REQUIRED');
 if(!transport||transport.offlineReview!==true||typeof transport.send!=='function')throw Error('OFFLINE_REVIEW_TRANSPORT_REQUIRED');
 if(typeof signer!=='function'||typeof nonceFactory!=='function'||typeof clock!=='function'||!webcrypto?.subtle)throw Error('REVIEW_SIGNER_AND_CLOCK_REQUIRED');
 const seen=new Set();
 async function call(kind,body={}){
  if(!Object.hasOwn(PATHS,kind))throw Error('PATH_NOT_ALLOWED');
  const timestamp=clock(),nonce=nonceFactory();
  if(!Number.isSafeInteger(timestamp)||timestamp<=0)throw Error('INVALID_TIMESTAMP');
  if(typeof nonce!=='string'||!/^[A-Za-z0-9_-]{16,80}$/.test(nonce)||seen.has(nonce))throw Error('NONCE_INVALID_OR_REUSED');
  seen.add(nonce);
  const text=JSON.stringify(body);
  if(enc.encode(text).byteLength>500000)throw Error('BODY_TOO_LARGE');
  const digest=hex(await webcrypto.subtle.digest('SHA-256',enc.encode(text)));
  const path=PATHS[kind],canonical=timestamp+'\n'+nonce+'\nPOST\n'+path+'\n'+digest;
  const signature=await signer(enc.encode(canonical));
  const b=signature instanceof Uint8Array?signature:new Uint8Array(signature||[]);
  if(b.length!==64)throw Error('ECDSA_P256_SIGNATURE_LENGTH_INVALID');
  const req={url:BASE+path,method:'POST',headers:{
    'content-type':'application/json','x-tens-timestamp':String(timestamp),
    'x-tens-nonce':nonce,'x-tens-signature':b64url(b)
   },body:text};
  let response;
  try{response=await transport.send(req)}
  catch{return kind==='claim'?{state:'CLAIM_UNCONFIRMED',reason:'TRANSPORT_UNCONFIRMED',status:0}:{status:0,state:'UNCONFIRMED',error:'TRANSPORT_UNCONFIRMED'}}
  const status=response?.status;
  if(!Number.isSafeInteger(status)||status<100||status>599)return kind==='claim'?{state:'CLAIM_UNCONFIRMED',status:0}:{status:0,state:'UNCONFIRMED'};
  let payload=null;
  try{payload=await response.json()}catch{}
  if(!payload||typeof payload!=='object'||Array.isArray(payload))return kind==='claim'?{state:'CLAIM_UNCONFIRMED',status}:{status,state:'UNCONFIRMED'};
  if(kind==='claim'){
   if(status!==200)return {state:'CLAIM_UNCONFIRMED',status,error:String(payload.error||'HTTP_REJECTED').slice(0,100)};
   if(payload.state==='EMPTY')return {state:'EMPTY',status:200};
   if(payload.state==='CLAIMED'&&typeof payload.jobId==='string'&&/^R20[23]WEB_[A-Za-z0-9_-]{20,80}$/.test(payload.jobId)&&
      typeof payload.question==='string'&&payload.question.length>0&&payload.question.length<=1200&&
      typeof payload.claimToken==='string'&&payload.claimToken.length>0)
       return {state:'CLAIMED',status:200,jobId:payload.jobId,question:payload.question,claimToken:payload.claimToken};
   return {state:'CLAIM_UNCONFIRMED',status:200,error:'MALFORMED_CLAIM_BODY'};
  }
  const ok=status===200&&payload.state===(kind==='complete'?'COMPLETE_ACCEPTED':'FAILURE_ACCEPTED');
  return ok?{status:200,state:payload.state}:{status,state:'UNCONFIRMED',error:String(payload.error||'NOT_ACCEPTED').slice(0,100)};
 }
 return Object.freeze({
  claim:()=>call('claim'),
  complete:args=>call('complete',args),
  fail:args=>call('fail',args)
 });
}
module.exports={createOfflineSignedQueueClient,REVIEW_ONLY_BASE:BASE};
